import pyomo.environ as pyo

DATA = {
    "products": ["laminate", "carpet"],
    "profit": {
        "laminate": 2.1,   # $ per sq ft
        "carpet": 3.3,     # $ per sq ft
    },
    "min_demand": {
        "laminate": 15000,  # sq ft/week, at least
        "carpet": 5000,     # sq ft/week, at least
    },
    "max_production": {
        "laminate": 40000,  # sq ft/week, at most (raw material shortage)
        "carpet": 20000,    # sq ft/week, at most (raw material shortage)
    },
    "min_total_shipment": 50000,  # sq ft/week, shipping contract total, at least
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of products
    model.P = pyo.Set(initialize=d["products"])

    # Decision variable: square feet produced weekly, per product.
    # Bounds: min demand <= x[p] <= max production.
    def var_bounds(m, p):
        return (d["min_demand"][p], d["max_production"][p])

    model.x = pyo.Var(model.P, domain=pyo.NonNegativeReals, bounds=var_bounds)

    # Objective: maximize total profit
    def profit_expr(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(expr=profit_expr, sense=pyo.maximize)

    # Shipping contract: total weekly volume must be at least 50,000 sq ft  (>=)
    def ship_rule(m):
        return sum(m.x[p] for p in m.P) >= d["min_total_shipment"]

    model.ship = pyo.Constraint(rule=ship_rule)

    return model


